{"command":"cat <<'EOF' > cmd/tparse/main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strings"
	"time"
)

type TestEvent struct {
	Time    time.Time `json:"Time"`
	Action  string    `json:"Action"`
	Package string    `json:"Package"`
	Test    string    `json:"Test"`
	Elapsed float64   `json:"Elapsed"`
	Output  string    `json:"Output"`
}

type Test struct {
	Name    string
	Package string
	Status  string
	Elapsed float64
	Output  []string
}

type Package struct {
	Name        string
	Status      string
	Elapsed     float64
	Coverage    string
	Tests       map[string]*Test
	TestNames   []string
	NoTestFiles bool
	Output      []string
	Cached      bool
}

var (
	allPtr         *bool
	passPtr        *bool
	skipPtr        *bool
	notestsPtr     *bool
	smallscreenPtr *bool
	slowPtr        *int
	sortPtr        *string
	nocolorPtr     *bool
	formatPtr      *string
	filePtr        *string
	trimpathPtr    *string
)

func main() {
	allPtr = flag.Bool("all", false, "")
	passPtr = flag.Bool("pass", false, "")
	skipPtr = flag.Bool("skip", false, "")
	notestsPtr = flag.Bool("notests", false, "")
	smallscreenPtr = flag.Bool("smallscreen", false, "")
	slowPtr = flag.Int("slow", 0, "")
	sortPtr = flag.String("sort", "name", "")
	nocolorPtr = flag.Bool("nocolor", false, "")
	formatPtr = flag.String("format", "basic", "")
	filePtr = flag.String("file", "", "")
	trimpathPtr = flag.String("trimpath", "", "")
	flag.Bool("v", false, "") // ignore version for now
	flag.Bool("follow", false, "")
	flag.String("follow-output", "", "")
	flag.Bool("include-timestamp", false, "")
	flag.Bool("progress", false, "")
	flag.String("compare", "", "")

	flag.Parse()

	if os.Getenv("NO_COLOR") != "" {
		*nocolorPtr = true
	}

	var reader io.Reader = os.Stdin
	if *filePtr != "" {
		f, err := os.Open(*filePtr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to open file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	}

	packages := make(map[string]*Package)
	var packageNames []string

	scanner := bufio.NewScanner(reader)
	for scanner.Scan() {
		var event TestEvent
		line := scanner.Bytes()
		if len(line) == 0 || line[0] != '{' {
			continue
		}
		if err := json.Unmarshal(line, &event); err != nil {
			continue
		}

		pkg, ok := packages[event.Package]
		if !ok {
			pkg = &Package{
				Name:  event.Package,
				Tests: make(map[string]*Test),
			}
			packages[event.Package] = pkg
			packageNames = append(packageNames, event.Package)
		}

		if event.Test != "" {
			t, ok := pkg.Tests[event.Test]
			if !ok {
				t = &Test{
					Name:    event.Test,
					Package: event.Package,
				}
				pkg.Tests[event.Test] = t
				pkg.TestNames = append(pkg.TestNames, event.Test)
			}

			switch event.Action {
			case "output":
				t.Output = append(t.Output, event.Output)
			case "pass", "fail", "skip":
				t.Status = strings.ToUpper(event.Action)
				t.Elapsed = event.Elapsed
			}
		} else {
			switch event.Action {
			case "output":
				pkg.Output = append(pkg.Output, event.Output)
				if strings.Contains(event.Output, "[no test files]") {
					pkg.NoTestFiles = true
				}
				if strings.Contains(event.Output, "(cached)") {
					pkg.Cached = true
				}
				reCover := regexp.MustCompile(`coverage: ([\d\.]+)%`)
				if matches := reCover.FindStringSubmatch(event.Output); len(matches) > 1 {
					pkg.Coverage = matches[1] + "%"
				}
			case "pass", "fail", "skip":
				pkg.Status = strings.ToUpper(event.Action)
				pkg.Elapsed = event.Elapsed
			}
		}
	}

	// Post-processing
	exitCode := 0
	for _, pkg := range packages {
		if pkg.Status == "FAIL" {
			exitCode = 1
			for _, t := range pkg.Tests {
				for _, out := range t.Output {
					if strings.Contains(out, "panic: ") {
						t.Status = "PANIC"
						pkg.Status = "PANIC"
					}
				}
			}
			for _, out := range pkg.Output {
				if strings.Contains(out, "panic: ") {
					pkg.Status = "PANIC"
				}
			}
		}
	}

    // Sort packages by name for consistent order in failure details
    sort.Strings(packageNames)

	// Implement rendering here...
    // (Skipping individual tests table for now to test the rest)

    // Failure details
    for _, name := range packageNames {
        pkg := packages[name]
        if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
            // Print package failure header
            // ...
        }
    }

	// Package summary table
    // ...

	os.Exit(exitCode)
}
EOF
"}

