				testsToDisplay = append(testsToDisplay, t)
			} else if *allPtr || (*passPtr && t.Status == "PASS") || (*skipPtr && t.Status == "SKIP") {
				testsToDisplay = append(testsToDisplay, t)
			}
		}
	}

	if (showTests || hasFailures) && len(testsToDisplay) > 0 {
		// Sort tests: by package name, then by elapsed descending
		sort.Slice(testsToDisplay, func(i, j int) bool {
			if testsToDisplay[i].Package != testsToDisplay[j].Package {
				return testsToDisplay[i].Package < testsToDisplay[j].Package
			}
			return testsToDisplay[i].Elapsed > testsToDisplay[j].Elapsed
		})

		if *slowPtr > 0 && len(testsToDisplay) > *slowPtr {
