func renderTestTable(tests []*Test, packages map[string]*Package) {
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	aligns := []int{1, 1, 0, 0}
	var rows [][]string
	lastPkg := ""
	for i, t := range tests {
		if i > 0 && t.Package != lastPkg && *slowPtr == 0 {
			rows = append(rows, []string{"", "", "", ""})
		}
		pkgName := t.Package
		if *trimpathPtr != "" {
			pkgName = strings.TrimPrefix(pkgName, *trimpathPtr)
		}
		if *smallscreenPtr {
			pkgName = lastPart(pkgName)
		}

		elapsed := fmt.Sprintf("%.2f", t.Elapsed)

		testName := t.Name
		if *smallscreenPtr && strings.Contains(testName, "/") {
			// Split test name
			parts := strings.Split(testName, "/")
			rows = append(rows, []string{t.Status, elapsed, parts[0], pkgName})
			for j := 1; j < len(parts); j++ {
				// This is a simplified version of splitting
				rows = append(rows, []string{"", "", " /" + parts[j], ""})
			}
		} else {
			rows = append(rows, []string{t.Status, elapsed, testName, pkgName})
		}
		lastPkg = t.Package
	}
	printTable(headers, rows, aligns, true)
}

func lastPart(path string) string {
	parts := strings.Split(path, "/")
	return parts[len(parts)-1]
}

func renderPackageTable(names []string, packages map[string]*Package) {
	// Sort names based on -sort flag
	sortedNames := make([]string, len(names))
	copy(sortedNames, names)
	sort.Slice(sortedNames, func(i, j int) bool {
		p1, p2 := packages[sortedNames[i]], packages[sortedNames[j]]
		// PANIC and FAIL always first?
		s1 := statusPriority(p1.Status)
		s2 := statusPriority(p2.Status)
		if s1 != s2 {
			return s1 < s2
		}

		switch *sortPtr {
		case "elapsed":
			return p1.Elapsed > p2.Elapsed
		case "cover":
			return p1.Coverage > p2.Coverage
		default:
			return sortedNames[i] < sortedNames[j]
		}
	})

	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{1, 1, 0, 1, 1, 1, 1}
	var rows [][]string
	for _, name := range sortedNames {
		p := packages[name]
		pkgName := p.Name
		if *trimpathPtr != "" {
			pkgName = strings.TrimPrefix(pkgName, *trimpathPtr)
		}
		if *smallscreenPtr {
			pkgName = lastPart(pkgName)
		}

		elapsed := fmt.Sprintf("%.2fs", p.Elapsed)
		if p.Cached {
			elapsed = "(cached)"
		}

		cover := p.Coverage
		if cover == "" {
			cover = "--"
		}

		pass, fail, skip := p.Counts()
		sPass, sFail, sSkip := strconv.Itoa(pass), strconv.Itoa(fail), strconv.Itoa(skip)
		if p.Status == "PANIC" || p.NoTestFiles {
			sPass, sFail, sSkip = "--", "--", "--"
		}

		row := []string{p.Status, elapsed, pkgName, cover, sPass, sFail, sSkip}
		if p.NoTestFiles {
			row[0] = "NOTEST"
			rows = append(rows, row)
			rows = append(rows, []string{"", "", "[no test files]", "", "", "", ""})
		} else {
			rows = append(rows, row)
		}
	}
	printTable(headers, rows, aligns, false)
}

func statusPriority(status string) int {
	switch status {
	case "PANIC": return 0
	case "FAIL": return 1
	case "PASS": return 2
	case "SKIP": return 3
	default: return 4
	}
}

func (p *Package) Counts() (pass, fail, skip int) {
	for _, t := range p.Tests {
		switch t.Status {
		case "PASS": pass++
		case "FAIL", "PANIC": fail++
		case "SKIP": skip++
		}
	}
	return
}

func printTable(headers []string, rows [][]string, aligns []int, isTestTable bool) {
	if *formatPtr == "plain" {
		printPlainTable(headers, rows, aligns)
		return
	}
	if *formatPtr == "markdown" {
		// Not implemented yet
	}

	// Basic format
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = utf8.RuneCountInString(h) + 2
	}
	for _, row := range rows {
		for i, cell := range row {
			w := utf8.RuneCountInString(cell) + 2
			if w > widths[i] {
				widths[i] = w
			}
		}
	}

	// Special case for Status column in package table (must be at least 8)
	if !isTestTable && widths[0] < 8 {
		widths[0] = 8
	} else if isTestTable && widths[0] < 8 {
		widths[0] = 8
	}

	// Print top border
	fmt.Print("╭")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 {
			fmt.Print("┬")
		}
	}
	fmt.Println("╮")

	// Print headers
	fmt.Print("│")
	for i, h := range headers {
		fmt.Print(formatCell(h, widths[i], 1, ""))
		fmt.Print("│")
	}
	fmt.Println()

	// Print separator
	fmt.Print("├")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 {
			fmt.Print("┼")
		}
	}
	fmt.Println("┤")

	// Print rows
	for _, row := range rows {
		if row[0] == "" && row[1] == "" && row[2] == "" && row[3] == "" && len(row) == 4 {
			// Empty line between packages in test table
			fmt.Print("│")
			for i, w := range widths {
				fmt.Print(strings.Repeat(" ", w))
				fmt.Print("│")
			}
			fmt.Println()
			continue
		}
		fmt.Print("│")
		for i, cell := range row {
			color := ""
			if i == 0 {
				color = getStatusColor(cell)
			}
			fmt.Print(formatCell(cell, widths[i], aligns[i], color))
			fmt.Print("│")
		}
		fmt.Println()
	}

	// Print bottom border
	fmt.Print("╰")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 {
			fmt.Print("┴")
		}
	}
	fmt.Println("╯")
}

func formatCell(content string, width int, align int, color string) string {
	cWidth := utf8.RuneCountInString(content)
	left, right := 0, 0
	switch align {
	case 0: // Left
		left = 1
		right = width - cWidth - left
	case 1: // Center
		total := width - cWidth
		left = total / 2
		right = total - left
	case 2: // Right
		right = 1
		left = width - cWidth - right
	}

	res := strings.Repeat(" ", left)
	if color != "" && !*nocolorPtr {
		res += color + content + "\033[0m"
	} else {
		res += content
	}
	res += strings.Repeat(" ", right)
	return res
}

func getStatusColor(status string) string {
	switch status {
	case "PASS": return "\033[92m"
	case "FAIL", "PANIC": return "\033[91m"
	case "SKIP", "NOTEST": return "\033[93m"
	default: return ""
	}
}

func renderFailHeader(pkg string) {
	pkgLine := "   FAIL  package: " + pkg + "   "
	width := utf8.RuneCountInString(pkgLine) + 2
	boxColor := "\033[38;5;103m"
	if *nocolorPtr {
		boxColor = ""
	}
	fmt.Printf("%s┏%s┓%s\n", boxColor, strings.Repeat("┃", width-2), "\033[0m") // Wait, top uses ━ not ┃
    // ... fixed below
}
// Rewriting headers
EOF
"}

