}

func renderPackageTable(names []string, packages map[string]*Package) {
	// Sort names based on -sort flag
	sortedNames := make([]string, len(names))
	copy(sortedNames, names)
	sort.Slice(sortedNames, func(i, j int) bool {
		p1, p2 := packages[sortedNames[i]], packages[sortedNames[j]]
		// PANIC and FAIL always first?
		s1 := statusPriority(p1.Status)
		s2 := statusPriority(p2.Status)
		if s1 != s2 {
			return s1 < s2
		}

		switch *sortPtr {
		case "elapsed":
			return p1.Elapsed > p2.Elapsed
		case "cover":
			return p1.Coverage > p2.Coverage
		default:
			return sortedNames[i] < sortedNames[j]
		}
	})

	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{1, 1, 0, 1, 1, 1, 1}
	var rows [][]string
	for _, name := range sortedNames {
		p := packages[name]
		pkgName := p.Name
		if *trimpathPtr != "" {
			pkgName = strings.TrimPrefix(pkgName, *trimpathPtr)
		}
		if *smallscreenPtr {
			pkgName = lastPart(pkgName)
		}

		elapsed := fmt.Sprintf("%.2fs", p.Elapsed)
		if p.Cached {
			elapsed = "(cached)"
		}

