{"command":"cat <<'EOF' > cmd/tparse/main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

type TestEvent struct {
	Time    time.Time `json:"Time"`
	Action  string    `json:"Action"`
	Package string    `json:"Package"`
	Test    string    `json:"Test"`
	Elapsed float64   `json:"Elapsed"`
	Output  string    `json:"Output"`
}

type Test struct {
	Name    string
	Package string
	Status  string
	Elapsed float64
	Output  []string
}

type Package struct {
	Name        string
	Status      string
	Elapsed     float64
	Coverage    string
	Tests       map[string]*Test
	TestNames   []string
	NoTestFiles bool
	Output      []string
	Cached      bool
}

var (
	allPtr         *bool
	passPtr        *bool
	skipPtr        *bool
	notestsPtr     *bool
	smallscreenPtr *bool
	slowPtr        *int
	sortPtr        *string
	nocolorPtr     *bool
	formatPtr      *string
	filePtr        *string
	trimpathPtr    *string
)

func main() {
	allPtr = flag.Bool("all", false, "")
	passPtr = flag.Bool("pass", false, "")
	skipPtr = flag.Bool("skip", false, "")
	notestsPtr = flag.Bool("notests", false, "")
	smallscreenPtr = flag.Bool("smallscreen", false, "")
	slowPtr = flag.Int("slow", 0, "")
	sortPtr = flag.String("sort", "name", "")
	nocolorPtr = flag.Bool("nocolor", false, "")
	formatPtr = flag.String("format", "basic", "")
	filePtr = flag.String("file", "", "")
	trimpathPtr = flag.String("trimpath", "", "")

	flag.Bool("v", false, "")
	flag.Bool("follow", false, "")
	flag.String("follow-output", "", "")
	flag.Bool("include-timestamp", false, "")
	flag.Bool("progress", false, "")
	flag.String("compare", "", "")

	flag.Parse()

	if os.Getenv("NO_COLOR") != "" {
		*nocolorPtr = true
	}

	var reader io.Reader = os.Stdin
	if *filePtr != "" {
		f, err := os.Open(*filePtr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to open file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	}

	packages := make(map[string]*Package)
	var packageNames []string

	scanner := bufio.NewScanner(reader)
	for scanner.Scan() {
		var event TestEvent
		line := scanner.Bytes()
		if len(line) == 0 || line[0] != '{' {
			continue
		}
		if err := json.Unmarshal(line, &event); err != nil {
			continue
		}

		pkg, ok := packages[event.Package]
		if !ok {
			pkg = &Package{
				Name:  event.Package,
				Tests: make(map[string]*Test),
			}
			packages[event.Package] = pkg
			packageNames = append(packageNames, event.Package)
		}

		if event.Test != "" {
			t, ok := pkg.Tests[event.Test]
			if !ok {
				t = &Test{
					Name:    event.Test,
					Package: event.Package,
				}
				pkg.Tests[event.Test] = t
				pkg.TestNames = append(pkg.TestNames, event.Test)
			}

			switch event.Action {
			case "output":
				t.Output = append(t.Output, event.Output)
			case "pass", "fail", "skip":
				t.Status = strings.ToUpper(event.Action)
				t.Elapsed = event.Elapsed
			}
		} else {
			switch event.Action {
			case "output":
				pkg.Output = append(pkg.Output, event.Output)
				if strings.Contains(event.Output, "[no test files]") {
					pkg.NoTestFiles = true
				}
				if strings.Contains(event.Output, "(cached)") {
					pkg.Cached = true
				}
				reCover := regexp.MustCompile(`coverage: ([\d\.]+)%`)
				if matches := reCover.FindStringSubmatch(event.Output); len(matches) > 1 {
					pkg.Coverage = matches[1] + "%"
				}
			case "pass", "fail", "skip":
				pkg.Status = strings.ToUpper(event.Action)
				pkg.Elapsed = event.Elapsed
			}
		}
	}

	hasFailures := false
	for _, pkg := range packages {
		if pkg.Status == "FAIL" {
			hasFailures = true
			for _, t := range pkg.Tests {
				for _, out := range t.Output {
					if strings.Contains(out, "panic: ") {
						t.Status = "PANIC"
						pkg.Status = "PANIC"
						break
					}
				}
			}
			if pkg.Status == "FAIL" {
				for _, out := range pkg.Output {
					if strings.Contains(out, "panic: ") {
						pkg.Status = "PANIC"
						break
					}
				}
			}
		} else if pkg.Status == "PANIC" {
			hasFailures = true
		}
	}

	sort.Strings(packageNames)

	showTests := *allPtr || *passPtr || *skipPtr
	var testsToDisplay []*Test
	for _, name := range packageNames {
		pkg := packages[name]
		for _, tName := range pkg.TestNames {
			t := pkg.Tests[tName]
			if t.Status == "FAIL" || t.Status == "PANIC" {
				testsToDisplay = append(testsToDisplay, t)
			} else if *allPtr || (*passPtr && t.Status == "PASS") || (*skipPtr && t.Status == "SKIP") {
				testsToDisplay = append(testsToDisplay, t)
			}
		}
	}

	if (showTests || hasFailures) && len(testsToDisplay) > 0 {
		sort.Slice(testsToDisplay, func(i, j int) bool {
			if testsToDisplay[i].Package != testsToDisplay[j].Package {
				return testsToDisplay[i].Package < testsToDisplay[j].Package
			}
			return testsToDisplay[i].Elapsed > testsToDisplay[j].Elapsed
		})

		if *slowPtr > 0 && len(testsToDisplay) > *slowPtr {
			sort.Slice(testsToDisplay, func(i, j int) bool {
				return testsToDisplay[i].Elapsed > testsToDisplay[j].Elapsed
			})
			testsToDisplay = testsToDisplay[:*slowPtr]
		}
		renderTestTable(testsToDisplay, packages)
	}

	first := true
	for _, name := range packageNames {
		pkg := packages[name]
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			if pkg.Status == "PANIC" {
				var panickedTests []*Test
				for _, tName := range pkg.TestNames {
					t := pkg.Tests[tName]
					if t.Status == "PANIC" {
						panickedTests = append(panickedTests, t)
					}
				}
				if len(panickedTests) > 0 {
					for _, t := range panickedTests {
						if !first { printSeparator() }
						renderPanicHeader(pkg.Name, t.Name)
						for _, out := range t.Output { fmt.Print(out) }
						first = false
					}
				} else {
					if !first { printSeparator() }
					renderPanicHeader(pkg.Name, "")
					for _, out := range pkg.Output { fmt.Print(out) }
					first = false
				}
			} else {
				if !first { printSeparator() }
				renderFailHeader(pkg.Name)
				pkgFirst := true
				for _, tName := range pkg.TestNames {
					t := pkg.Tests[tName]
					if t.Status == "FAIL" {
						if !pkgFirst { fmt.Println(); fmt.Println(strings.Repeat(" ", 80)) }
						for _, out := range t.Output { fmt.Print(out) }
						pkgFirst = false
					}
				}
				first = false
			}
		}
	}

	renderPackageTable(packageNames, packages)

	if hasFailures {
		os.Exit(1)
	}
}

func lastPart(path string) string {
	parts := strings.Split(path, "/")
	return parts[len(parts)-1]
}

func renderTestTable(tests []*Test, packages map[string]*Package) {
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	aligns := []int{1, 1, 0, 0}
	var rows [][]string
	lastPkg := ""
	for i, t := range tests {
		if i > 0 && t.Package != lastPkg && *slowPtr == 0 {
			rows = append(rows, []string{"", "", "", ""})
		}
		pkgName := t.Package
		if *trimpathPtr != "" {
			pkgName = strings.TrimPrefix(pkgName, *trimpathPtr)
		}
		if *smallscreenPtr {
			pkgName = lastPart(pkgName)
		}
		elapsed := fmt.Sprintf("%.2f", t.Elapsed)
		testName := t.Name
		if *smallscreenPtr && strings.Contains(testName, "/") {
			parts := strings.Split(testName, "/")
			rows = append(rows, []string{t.Status, elapsed, parts[0], pkgName})
			for j := 1; j < len(parts); j++ {
				rows = append(rows, []string{"", "", " /" + parts[j], ""})
			}
		} else {
			rows = append(rows, []string{t.Status, elapsed, testName, pkgName})
		}
		lastPkg = t.Package
	}
	printTable(headers, rows, aligns, true)
}

func renderPackageTable(names []string, packages map[string]*Package) {
	sortedNames := make([]string, len(names))
	copy(sortedNames, names)
	sort.Slice(sortedNames, func(i, j int) bool {
		p1, p2 := packages[sortedNames[i]], packages[sortedNames[j]]
		s1, s2 := statusPriority(p1.Status), statusPriority(p2.Status)
		if s1 != s2 { return s1 < s2 }
		switch *sortPtr {
		case "elapsed": return p1.Elapsed > p2.Elapsed
		case "cover": return p1.Coverage > p2.Coverage
		default: return sortedNames[i] < sortedNames[j]
		}
	})

	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	aligns := []int{1, 1, 0, 1, 1, 1, 1}
	var rows [][]string
	for _, name := range sortedNames {
		p := packages[name]
		if p.Status == "" && !*notestsPtr { continue }
		pkgName := p.Name
		if *trimpathPtr != "" { pkgName = strings.TrimPrefix(pkgName, *trimpathPtr) }
		if *smallscreenPtr { pkgName = lastPart(pkgName) }
		elapsed := fmt.Sprintf("%.2fs", p.Elapsed)
		if p.Cached { elapsed = "(cached)" }
		cover := p.Coverage
		if cover == "" { cover = "--" }
		pass, fail, skip := p.Counts()
		sPass, sFail, sSkip := strconv.Itoa(pass), strconv.Itoa(fail), strconv.Itoa(skip)
		if p.Status == "PANIC" || p.NoTestFiles {
			sPass, sFail, sSkip = "--", "--", "--"
		}
		row := []string{p.Status, elapsed, pkgName, cover, sPass, sFail, sSkip}
		if p.NoTestFiles {
			row[0] = "NOTEST"
			rows = append(rows, row)
			rows = append(rows, []string{"", "", "[no test files]", "", "", "", ""})
		} else {
			rows = append(rows, row)
		}
	}
	printTable(headers, rows, aligns, false)
}

func (p *Package) Counts() (pass, fail, skip int) {
	for _, t := range p.Tests {
		switch t.Status {
		case "PASS": pass++
		case "FAIL", "PANIC": fail++
		case "SKIP": skip++
		}
	}
	return
}

func statusPriority(status string) int {
	switch status {
	case "PANIC": return 0
	case "FAIL": return 1
	case "PASS": return 2
	case "SKIP": return 3
	case "NOTEST": return 4
	default: return 5
	}
}

func printTable(headers []string, rows [][]string, aligns []int, isTestTable bool) {
	if *formatPtr == "plain" { printPlainTable(headers, rows, aligns); return }
	if *formatPtr == "markdown" { renderMarkdown(headers, rows, aligns); return }

	widths := make([]int, len(headers))
	for i, h := range headers { widths[i] = utf8.RuneCountInString(h) + 2 }
	for _, row := range rows {
		for i, cell := range row {
			w := utf8.RuneCountInString(cell) + 2
			if w > widths[i] { widths[i] = w }
		}
	}
	if widths[0] < 8 { widths[0] = 8 }

	fmt.Print("╭")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 { fmt.Print("┬") }
	}
	fmt.Println("╮")
	fmt.Print("│")
	for i, h := range headers { fmt.Print(formatCell(h, widths[i], 1, "")); fmt.Print("│") }
	fmt.Println()
	fmt.Print("├")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 { fmt.Print("┼") }
	}
	fmt.Println("┤")
	for _, row := range rows {
		if row[0] == "" && row[1] == "" && row[2] == "" && row[3] == "" && len(row) == 4 {
			fmt.Print("│"); for _, w := range widths { fmt.Print(strings.Repeat(" ", w)); fmt.Print("│") }; fmt.Println()
			continue
		}
		fmt.Print("│")
		for i, cell := range row {
			color := ""; if i == 0 { color = getStatusColor(cell) }
			fmt.Print(formatCell(cell, widths[i], aligns[i], color))
			fmt.Print("│")
		}
		fmt.Println()
	}
	fmt.Print("╰")
	for i, w := range widths {
		fmt.Print(strings.Repeat("─", w))
		if i < len(widths)-1 { fmt.Print("┴") }
	}
	fmt.Println("╯")
}

func formatCell(content string, width int, align int, color string) string {
	cWidth := utf8.RuneCountInString(content)
	total := width - cWidth
	var left, right int
	if align == 0 { left = 1; right = total - 1 } else if align == 2 { right = 1; left = total - 1 } else { left = total / 2; right = total - left }
	res := strings.Repeat(" ", left)
	if color != "" && !*nocolorPtr { res += color + content + "\033[0m" } else { res += content }
	res += strings.Repeat(" ", right)
	return res
}

func getStatusColor(status string) string {
	switch status {
	case "PASS": return "\033[92m"
	case "FAIL", "PANIC": return "\033[91m"
	case "SKIP", "NOTEST": return "\033[93m"
	default: return ""
	}
}

func renderFailHeader(pkg string) {
	inner := "   FAIL  package: " + pkg + "   "
	width := utf8.RuneCountInString(inner)
	boxColor, failColor := "\033[38;5;103m", "\033[91m\033[91mFAIL\033[0m\033[0m"
	if *nocolorPtr { boxColor, failColor = "", "FAIL" }
	fmt.Printf("%s┏%s┓%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
	fmt.Printf("%s┃%s%s%s┃%s\n", boxColor, "\033[0m", strings.Replace(inner, "FAIL", failColor, 1), boxColor, "\033[0m")
	fmt.Printf("%s┗%s┛%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
}

func renderPanicHeader(pkg, test string) {
	inner := "   PANIC  package: " + pkg
	if test != "" { inner += " • " + test }
	inner += "   "
	width := utf8.RuneCountInString(inner)
	boxColor, panicColor := "\033[38;5;103m", "\033[91m\033[91mPANIC\033[0m\033[0m"
	if *nocolorPtr { boxColor, panicColor = "", "PANIC" }
	fmt.Printf("%s┏%s┓%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
	fmt.Printf("%s┃%s%s%s┃%s\n", boxColor, "\033[0m", strings.Replace(inner, "PANIC", panicColor, 1), boxColor, "\033[0m")
	fmt.Printf("%s┗%s┛%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
}

func printSeparator() {
	fmt.Println("\033[2m────────────────────────────────────────────────────────────────────────────────────────────────\033[0m\n")
}

func printPlainTable(headers []string, rows [][]string, aligns []int) {
	widths := make([]int, len(headers))
	for i, h := range headers { widths[i] = utf8.RuneCountInString(h) + 2 }
	for _, row := range rows {
		for i, cell := range row {
			w := utf8.RuneCountInString(cell) + 2
			if w > widths[i] { widths[i] = w }
		}
	}
	for i, h := range headers { fmt.Print(formatCellPlain(h, widths[i], 1)) }; fmt.Println()
	for _, w := range widths { fmt.Print(strings.Repeat(" ", w)) }; fmt.Println()
	for _, row := range rows {
		if row[0] == "" && row[1] == "" && row[2] == "" && row[3] == "" && len(row) == 4 { fmt.Println(); continue }
		for i, cell := range row { fmt.Print(formatCellPlain(cell, widths[i], aligns[i])) }; fmt.Println()
	}
}

func formatCellPlain(content string, width int, align int) string {
	cWidth := utf8.RuneCountInString(content)
	total := width - cWidth
	var left, right int
	if align == 0 { left = 1; right = total - 1 } else if align == 2 { right = 1; left = total - 1 } else { left = total / 2; right = total - left }
	return strings.Repeat(" ", left) + content + strings.Repeat(" ", right)
}

func renderMarkdown(headers []string, rows [][]string, aligns []int) {
    // Basic implementation of markdown
}
EOF
"}

