	fmt.Printf("%s┗%s┛%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
}

func renderPanicHeader(pkg, test string) {
	inner := "   PANIC  package: " + pkg
	if test != "" { inner += " • " + test }
	inner += "   "
	width := utf8.RuneCountInString(inner)
	boxColor, panicColor := "\033[38;5;103m", "\033[91m\033[91mPANIC\033[0m\033[0m"
	if *nocolorPtr { boxColor, panicColor = "", "PANIC" }
	fmt.Printf("%s┏%s┓%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
	if !*nocolorPtr {
		fmt.Printf("%s┃%s%s%s┃%s\n", boxColor, "\033[0m", strings.Replace(inner, "PANIC", panicColor, 1), boxColor, "\033[0m")
	} else {
		fmt.Printf("┃%s┃\n", inner)
	}
	fmt.Printf("%s┗%s┛%s\n", boxColor, strings.Repeat("━", width), "\033[0m")
}

func printSeparator() {
	fmt.Println("\033[2m────────────────────────────────────────────────────────────────────────────────────────────────\033[0m\n")
}

func printPlainTable(headers []string, rows [][]string, aligns []int) {
	widths := make([]int, len(headers))
	for i, h := range headers { widths[i] = utf8.RuneCountInString(h) + 2 }
	for _, row := range rows {
		for i, cell := range row {
			w := utf8.RuneCountInString(cell) + 2
			if w > widths[i] { widths[i] = w }
		}
	}
	for i, h := range headers { fmt.Print(formatCellPlain(h, widths[i], 1)) }; fmt.Println()
	for _, w := range widths { fmt.Print(strings.Repeat(" ", w)) }; fmt.Println()
	for _, row := range rows {
		if row[0] == "" && row[1] == "" && row[2] == "" && row[3] == "" && len(row) == 4 { fmt.Println(); continue }
		for i, cell := range row { fmt.Print(formatCellPlain(cell, widths[i], aligns[i])) }; fmt.Println()
	}
}

func formatCellPlain(content string, width int, align int) string {
	cWidth := utf8.RuneCountInString(content)
	total := width - cWidth
	var left, right int
	if align == 0 { left = 1; right = total - 1 } else if align == 2 { right = 1; left = total - 1 } else { left = total / 2; right = total - left }
	return strings.Repeat(" ", left) + content + strings.Repeat(" ", right)
}
